const pptxgen = require("pptxgenjs");
const path = require("path");

// Color palette - Cloudflare-inspired dark theme
const C = {
  darkBg:      "0D1B2A",   // deep navy - title slides
  mediumBg:    "1B263B",   // medium navy - content slides
  accent:      "F97316",   // Cloudflare orange
  accentLight: "FDBA74",   // light orange
  text:        "E2E8F0",   // light gray text
  textMuted:   "94A3B8",   // muted text
  white:       "FFFFFF",
  chartBlue:   "3B82F6",
  chartTeal:   "06B6D4",
  chartGreen:  "10B981",
  chartRed:    "EF4444",
  chartYellow: "F59E0B",
  tableHeader: "1E3A5F",
  tableAlt:    "1B263B",
};

// Image paths
const ASSETS = "/app/benchmark/assets/";

// Helper: card with accent bar
function addCard(slide, x, y, w, h, opts = {}) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: opts.fill || "1B263B" },
    line: opts.line || { color: "334155", width: 0.5 },
  });
  // Left accent bar
  slide.addShape("rect", {
    x, y, w: 0.06, h,
    fill: { color: opts.accent || C.accent },
  });
}

function bigStat(slide, x, y, value, label, opts = {}) {
  slide.addText(value, {
    x, y, w: opts.w || 2.5, h: 0.7,
    fontSize: opts.fontSize || 44, bold: true,
    color: opts.color || C.accent,
    fontFace: "Arial Black", align: "center", valign: "bottom", margin: 0,
  });
  slide.addText(label, {
    x, y: y + 0.68, w: opts.w || 2.5, h: 0.4,
    fontSize: 11, color: C.textMuted, fontFace: "Arial",
    align: "center", valign: "top", margin: 0,
  });
}

function slideTitle(slide, title, subtitle = "") {
  slide.addText(title, {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, bold: true, color: C.white,
    fontFace: "Arial", margin: 0,
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.5, y: 0.85, w: 9, h: 0.35,
      fontSize: 13, color: C.textMuted, fontFace: "Arial", margin: 0,
    });
  }
  // Orange underline accent
  slide.addShape("rect", {
    x: 0.5, y: 1.15, w: 1.2, h: 0.04,
    fill: { color: C.accent },
  });
}

function footer(slide, text) {
  slide.addText(text || "Source: Cloudflare Radar 2024 Year in Review", {
    x: 0.5, y: 5.3, w: 6, h: 0.25,
    fontSize: 8, color: "475569", fontFace: "Arial", margin: 0,
  });
}

// ─── BUILD PRESENTATION ────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Cloudflare Radar 2024 Year in Review";
pres.author = "Cloudflare";

// ══════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ══════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
  sl.background = { color: C.darkBg };

  // Large decorative circle (bottom-right, subtle)
  sl.addShape("ellipse", {
    x: 6.5, y: 2.5, w: 5, h: 5,
    fill: { color: C.accent, transparency: 92 },
    line: { color: C.accent, width: 1, transparency: 70 },
  });

  // Top-left small circle
  sl.addShape("ellipse", {
    x: -0.8, y: -0.8, w: 2.5, h: 2.5,
    fill: { color: C.accent, transparency: 88 },
    line: { width: 0 },
  });

  // Logo text / brand
  sl.addText("CLOUDFLARE RADAR", {
    x: 0.6, y: 1.4, w: 5, h: 0.5,
    fontSize: 14, bold: true, color: C.accent,
    fontFace: "Arial Black", charSpacing: 4, margin: 0,
  });

  sl.addText("2024 Year in Review", {
    x: 0.6, y: 1.95, w: 8, h: 1.3,
    fontSize: 46, bold: true, color: C.white,
    fontFace: "Arial Black", margin: 0,
  });

  sl.addText("Global Internet Traffic, Adoption Trends,\nConnectivity Disruptions & Security Insights", {
    x: 0.6, y: 3.3, w: 6, h: 0.9,
    fontSize: 15, color: C.textMuted, fontFace: "Arial", margin: 0,
  });

  sl.addShape("rect", {
    x: 0.6, y: 4.35, w: 1.5, h: 0.05,
    fill: { color: C.accent },
  });

  sl.addText("Prepared for Technology Executives & Network Infrastructure Leaders", {
    x: 0.6, y: 4.55, w: 6, h: 0.4,
    fontSize: 11, color: C.textMuted, fontFace: "Arial", margin: 0,
  });

  sl.addText("radar.cloudflare.com", {
    x: 7.5, y: 5.1, w: 2.2, h: 0.3,
    fontSize: 10, color: "334155", fontFace: "Arial",
    align: "right", margin: 0,
  });
}

// ══════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Traffic Growth & Starlink
// ══════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
