  // Left column: main stats
  addCard(sl, 0.5, 1.35, 4.2, 1.5);
  sl.addText("17%", {
    x: 0.7, y: 1.5, w: 1.8, h: 0.8,
    fontSize: 52, bold: true, color: C.accent,
    fontFace: "Arial Black", align: "left", valign: "middle", margin: 0,
  });
  sl.addText("Year-over-Year\nGlobal Traffic Growth", {
    x: 2.5, y: 1.55, w: 2.0, h: 0.8,
    fontSize: 13, color: C.text, fontFace: "Arial", valign: "middle", margin: 0,
  });
  sl.addText("Trend line normalized from mid-January to account for post-holiday activity", {
    x: 0.7, y: 2.45, w: 3.8, h: 0.3,
    fontSize: 9, color: C.textMuted, fontFace: "Arial", margin: 0,
  });

  // Starlink card
  addCard(sl, 0.5, 3.0, 4.2, 1.85, { accent: C.chartYellow });
  sl.addText("3.3x", {
    x: 0.7, y: 3.15, w: 1.6, h: 0.8,
    fontSize: 52, bold: true, color: C.chartYellow,
    fontFace: "Arial Black", align: "left", valign: "middle", margin: 0,
  });
  sl.addText("Starlink\nTraffic Surge", {
    x: 2.4, y: 3.2, w: 2.0, h: 0.75,
    fontSize: 14, color: C.text, fontFace: "Arial", bold: true, valign: "middle", margin: 0,
  });
  sl.addText("SpaceX Starlink brought satellite Internet connectivity to previously underserved locations throughout 2024", {
    x: 0.7, y: 4.0, w: 3.8, h: 0.65,
    fontSize: 10, color: C.textMuted, fontFace: "Arial", margin: 0,
  });

  // Right: Starlink image
  sl.addImage({
    path: ASSETS + "starlink-traffic-growth-2024.jpg",
    x: 5.0, y: 1.35, w: 4.5, h: 3.5,
    sizing: { type: "cover", w: 4.5, h: 3.5 },
  });

  // Additional context bar at bottom
  sl.addShape("rect", {
    x: 0.5, y: 5.0, w: 9, h: 0.04,
    fill: { color: "334155" },
  });
  sl.addText("Traffic growth driven by increasing reliance on the Internet for communication, commerce, entertainment & transportation", {
    x: 0.5, y: 5.1, w: 9, h: 0.3,
    fontSize: 9, color: C.textMuted, fontFace: "Arial", margin: 0,
  });

  footer(sl);
}

// ══════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Top 10 Services + Gen AI
// ══════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
  sl.background = { color: C.mediumBg };

  slideTitle(sl, "Google Leads Top 10 Services as Generative AI Rises",
    "Ranking based on aggregate DNS resolver data from Cloudflare's 1.1.1.1 — generative AI saw meteoric growth in 2024");

  // Left: top-10 table
  const rows = [
    [{ text: "#", options: { bold: true, color: C.white, fill: { color: C.tableHeader }, align: "center" } },
     { text: "Service", options: { bold: true, color: C.white, fill: { color: C.tableHeader } } },
     { text: "#", options: { bold: true, color: C.white, fill: { color: C.tableHeader }, align: "center" } },
     { text: "Service", options: { bold: true, color: C.white, fill: { color: C.tableHeader } } }],
