// Helper: card with accent bar
function addCard(slide, x, y, w, h, opts = {}) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: opts.fill || "1B263B" },
    line: opts.line || { color: "334155", width: 0.5 },
  });
  // Left accent bar
  slide.addShape("rect", {
    x, y, w: 0.06, h,
    fill: { color: opts.accent || C.accent },
  });
}

function bigStat(slide, x, y, value, label, opts = {}) {
  slide.addText(value, {
    x, y, w: opts.w || 2.5, h: 0.7,
    fontSize: opts.fontSize || 44, bold: true,
    color: opts.color || C.accent,
    fontFace: "Arial Black", align: "center", valign: "bottom", margin: 0,
  });
  slide.addText(label, {
    x, y: y + 0.68, w: opts.w || 2.5, h: 0.4,
    fontSize: 11, color: C.textMuted, fontFace: "Arial",
    align: "center", valign: "top", margin: 0,
  });
}

function slideTitle(slide, title, subtitle = "") {
  slide.addText(title, {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, bold: true, color: C.white,
    fontFace: "Arial", margin: 0,
