      x: 0.5, y: 0.85, w: 9, h: 0.35,
      fontSize: 13, color: C.textMuted, fontFace: "Arial", margin: 0,
    });
  }
  // Orange underline accent
  slide.addShape("rect", {
    x: 0.5, y: 1.15, w: 1.2, h: 0.04,
    fill: { color: C.accent },
  });
}

function footer(slide, text) {
  slide.addText(text || "Source: Cloudflare Radar 2024 Year in Review", {
    x: 0.5, y: 5.3, w: 6, h: 0.25,
